// Brutalist CV layouts. Exports CVA, CVB, CVC to window. Uses INK/PAPER/VIOLET from portfolio-shared.jsx.

const SANS = 'Inter, system-ui, sans-serif'
const MONO = "'Space Mono', monospace"

const EXPERIENCE = [
  { role: 'senior software engineer', org: 'gartner', loc: 'barcelona', time: '2024 - 2025', bullets: [
    'supported vendor portal (react router v7 / ts)',
    'built partner portal from scratch (vercel / github actions / cypress)',
    'led app router, server components and actions migrations (next.js)',
  ]},
  { role: 'software engineer', org: 'gartner', loc: 'barcelona', time: '2022 - 2024', bullets: [
    'supported capterra.com (next.js / ts)',
    'migrated microfrontends into unified monorepo (aws -> vercel)',
    'managed observability integrations (datadog / newrelic)',
  ]},
  { role: 'associate software engineer', org: 'gartner', loc: 'barcelona', time: '2018 - 2022', bullets: [
    'supported getapp.com (sintra / ruby)',
    'migrated getapp frontend (jquery -> react)',
    'managed SEM landing pages (+10M \u20ac/year revenue)',
  ]},
  { role: 'junior software engineer', org: 'gartner', loc: 'barcelona', time: '2018', bullets: [
    'completed 6 months of intensive tech training at the company',
    'built apps to consolidate skills (ruby / mysql / jquery)',
    'offered permanent job as 1 of 3 successful candidates (out of 6)',
  ]},
  { role: 'mechanical engineer', org: 'demola project', loc: 'tampere', time: '2017', bullets: [
    'designed a specialized drone capable of taking soil samples',
    'modeled structure and internal mechanisms (solidworks)',
    'won 2nd place out of 30 projects at demola spring 2017',
  ]},
]

const SKILLS = [
  { cat: 'languages', items: ['typescript', 'node', 'graphql', 'ruby'] },
  { cat: 'libraries', items: ['react', 'tailwind', 'zustand', 'testing library'] },
  { cat: 'frameworks', items: ['next.js', 'router v7', 'vitest', 'playwright'] },
  { cat: 'tools', items: ['git', 'vite', 'mysql', 'docker'] },
  { cat: 'cloud', items: ['aws', 'vercel', 'actions', 'datadog'] },
]

const EDUCATION = [
  { title: 'java web developer bootcamp', org: 'ubiqum', loc: 'barcelona', time: '2017' },
  { title: 'mechanical engineering degree', org: 'eseiaat', loc: 'terrassa', time: '2013 - 2016' },
]

const LANGS = ['catalan', 'spanish', 'english', 'japanese']

const PROFILE = "i have always been a builder at heart, which naturally drew me to study mechanical engineering. 8 years ago, i took my passion for building into the digital realm to become a software engineer. the vibrant tech community and the endless possibilities of software have kept me hooked ever since. today, i'm combining my engineering mindset with the superpowers of AI to push the boundaries of what i can build with code."

const CONTACT = [
  ['email', 'fran.altes@gmail.com'],
  ['site', 'fran-altes.com'],
  ['github', 'francesc-altes'],
  ['handle', 'suki60'],
]

function Label({ children }) {
  return <div style={{ fontFamily: MONO, fontSize: 11, letterSpacing: '0.08em', color: INK, opacity: 0.55, textTransform: 'uppercase', marginBottom: 10 }}>[ {children} ]</div>
}

function Page({ w, children }) {
  return <div style={{ width: w, background: PAPER, color: INK, boxSizing: 'border-box', border: `2px solid ${INK}` }}>{children}</div>
}

// A — Faithful ledger: single column, squared header block, monospace rules.
function CVA() {
  return (
    <Page w={900}>
      <div style={{ padding: '40px 48px', borderBottom: `2px solid ${INK}` }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end' }}>
          <h1 style={{ fontFamily: SANS, fontWeight: 900, fontSize: 64, letterSpacing: '-0.04em', margin: 0, textTransform: 'lowercase' }}>francesc altes</h1>
          <div style={{ fontFamily: MONO, fontSize: 13, textAlign: 'right', lineHeight: 1.7 }}>
            {CONTACT.map(([k, v]) => <div key={k}><span style={{ opacity: 0.5 }}>{k}</span>&nbsp; {v}</div>)}
          </div>
        </div>
        <div style={{ fontFamily: MONO, fontSize: 13, letterSpacing: '0.08em', marginTop: 10, textTransform: 'uppercase', opacity: 0.65 }}>senior software engineer</div>
      </div>
      <div style={{ padding: '32px 48px', borderBottom: `2px solid ${INK}` }}>
        <Label>profile</Label>
        <p style={{ fontFamily: SANS, fontSize: 16, lineHeight: 1.55, margin: 0, maxWidth: 700 }}>{PROFILE}</p>
      </div>
      <div style={{ padding: '32px 48px', borderBottom: `2px solid ${INK}` }}>
        <Label>experience</Label>
        {EXPERIENCE.map((e, i) => (
          <div key={i} style={{ display: 'flex', gap: 24, padding: '16px 0', borderTop: i ? `1px solid rgba(10,10,10,0.15)` : 'none' }}>
            <div style={{ width: 130, flexShrink: 0, fontFamily: MONO, fontSize: 12, opacity: 0.6 }}>{e.time}</div>
            <div style={{ flex: 1 }}>
              <div style={{ fontFamily: SANS, fontWeight: 700, fontSize: 17, textTransform: 'lowercase' }}>{e.role}</div>
              <div style={{ fontFamily: MONO, fontSize: 12, opacity: 0.55, marginBottom: 8 }}>{e.org} / {e.loc}</div>
              {e.bullets.map((b, j) => <div key={j} style={{ fontFamily: SANS, fontSize: 14, lineHeight: 1.5, opacity: 0.85 }}>— {b}</div>)}
            </div>
          </div>
        ))}
      </div>
      <div style={{ display: 'flex', borderBottom: `2px solid ${INK}` }}>
        <div style={{ flex: 1, padding: '32px 48px', borderRight: `2px solid ${INK}` }}>
          <Label>skills</Label>
          {SKILLS.map(s => (
            <div key={s.cat} style={{ marginBottom: 10 }}>
              <div style={{ fontFamily: MONO, fontSize: 11, opacity: 0.5, textTransform: 'uppercase' }}>{s.cat}</div>
              <div style={{ fontFamily: SANS, fontSize: 14 }}>{s.items.join(' \u00b7 ')}</div>
            </div>
          ))}
        </div>
        <div style={{ width: 280, padding: '32px 48px' }}>
          <Label>education</Label>
          {EDUCATION.map((ed, i) => (
            <div key={i} style={{ marginBottom: 14 }}>
              <div style={{ fontFamily: SANS, fontWeight: 700, fontSize: 14, textTransform: 'lowercase' }}>{ed.title}</div>
              <div style={{ fontFamily: MONO, fontSize: 11, opacity: 0.55 }}>{ed.org} / {ed.loc} / {ed.time}</div>
            </div>
          ))}
          <Label>languages</Label>
          <div style={{ fontFamily: SANS, fontSize: 14 }}>{LANGS.join(' \u00b7 ')}</div>
        </div>
      </div>
      <div style={{ padding: '14px 48px', fontFamily: MONO, fontSize: 11, opacity: 0.45, textTransform: 'lowercase' }}>[ resume — updated 2026 ]</div>
    </Page>
  )
}

// B — Sidebar ledger: violet sidebar with contact/skills/education, main column experience.
function CVB() {
  return (
    <Page w={900}>
      <div style={{ display: 'flex' }}>
        <div style={{ width: 300, background: VIOLET, borderRight: `2px solid ${INK}`, padding: '40px 32px', boxSizing: 'border-box' }}>
          <div style={{ position: 'relative', width: 160, marginBottom: 20 }}>
            <div style={{ position: 'absolute', top: 10, left: 10, width: '100%', aspectRatio: '1 / 1', borderRadius: '50%', background: VIOLET }} />
            <img src="data:image/jpeg;base64," alt="francesc altes" style={{ position: 'relative', width: '100%', aspectRatio: '1 / 1', objectFit: 'cover', borderRadius: '50%', border: `3px solid ${INK}`, display: 'block' }} />
          </div>
          <h1 style={{ fontFamily: SANS, fontWeight: 900, fontSize: 40, lineHeight: 0.95, letterSpacing: '-0.03em', margin: '0 0 6px', textTransform: 'lowercase' }}>francesc altes</h1>
          <div style={{ fontFamily: MONO, fontSize: 12, textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 32 }}>senior software engineer</div>
          <Label>contact</Label>
          <div style={{ fontFamily: MONO, fontSize: 12, lineHeight: 2, marginBottom: 28 }}>
            {CONTACT.map(([k, v]) => <div key={k}>{v}</div>)}
          </div>
          <Label>skills</Label>
          {SKILLS.map(s => (
            <div key={s.cat} style={{ marginBottom: 12 }}>
              <div style={{ fontFamily: MONO, fontSize: 10, opacity: 0.6, textTransform: 'uppercase' }}>{s.cat}</div>
              <div style={{ fontFamily: SANS, fontSize: 13, lineHeight: 1.5 }}>{s.items.join(', ')}</div>
            </div>
          ))}
          <Label>education</Label>
          {EDUCATION.map((ed, i) => (
            <div key={i} style={{ marginBottom: 12 }}>
              <div style={{ fontFamily: SANS, fontWeight: 700, fontSize: 13, textTransform: 'lowercase' }}>{ed.title}</div>
              <div style={{ fontFamily: MONO, fontSize: 10, opacity: 0.6 }}>{ed.org} / {ed.time}</div>
            </div>
          ))}
          <Label>languages</Label>
          <div style={{ fontFamily: SANS, fontSize: 13 }}>{LANGS.join(', ')}</div>
        </div>
        <div style={{ flex: 1, padding: '40px 36px', boxSizing: 'border-box' }}>
          <Label>profile</Label>
          <p style={{ fontFamily: SANS, fontSize: 15, lineHeight: 1.55, margin: '0 0 28px' }}>{PROFILE}</p>
          <Label>experience</Label>
          {EXPERIENCE.map((e, i) => (
            <div key={i} style={{ padding: '14px 0', borderTop: i ? `1px solid rgba(10,10,10,0.15)` : 'none' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>
                <div style={{ fontFamily: SANS, fontWeight: 700, fontSize: 16, textTransform: 'lowercase' }}>{e.role}</div>
                <div style={{ fontFamily: MONO, fontSize: 11, opacity: 0.5 }}>{e.time}</div>
              </div>
              <div style={{ fontFamily: MONO, fontSize: 11, opacity: 0.55, marginBottom: 6 }}>{e.org} / {e.loc}</div>
              {e.bullets.map((b, j) => <div key={j} style={{ fontFamily: SANS, fontSize: 13, lineHeight: 1.5, opacity: 0.85 }}>— {b}</div>)}
            </div>
          ))}
        </div>
      </div>
    </Page>
  )
}

// C — Editorial: big name statement, index-numbered experience entries like the projects list.
function CVC() {
  return (
    <Page w={900}>
      <div style={{ padding: '48px 48px 32px', borderBottom: `2px solid ${INK}` }}>
        <div style={{ fontFamily: MONO, fontSize: 12, opacity: 0.55, marginBottom: 14 }}>[ resume ]</div>
        <h1 style={{ fontFamily: SANS, fontWeight: 900, fontSize: 88, lineHeight: 0.85, letterSpacing: '-0.045em', margin: 0, textTransform: 'lowercase' }}>francesc<br />altes</h1>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginTop: 18 }}>
          <div style={{ fontFamily: MONO, fontSize: 13, textTransform: 'uppercase', letterSpacing: '0.06em' }}>senior software engineer</div>
          <div style={{ fontFamily: MONO, fontSize: 12, textAlign: 'right', lineHeight: 1.7 }}>
            {CONTACT.map(([k, v]) => <div key={k}>{v}</div>)}
          </div>
        </div>
      </div>
      <div style={{ padding: '28px 48px', borderBottom: `2px solid ${INK}`, background: VIOLET }}>
        <p style={{ fontFamily: SANS, fontSize: 17, lineHeight: 1.55, margin: 0, maxWidth: 720 }}>{PROFILE}</p>
      </div>
      <div style={{ padding: '32px 48px', borderBottom: `2px solid ${INK}` }}>
        <Label>experience</Label>
        {EXPERIENCE.map((e, i) => (
          <div key={i} style={{ display: 'flex', gap: 20, padding: '18px 0', borderTop: i ? `1px solid rgba(10,10,10,0.15)` : 'none' }}>
            <div style={{ fontFamily: MONO, fontSize: 22, fontWeight: 700, opacity: 0.25, width: 40 }}>{String(i + 1).padStart(2, '0')}</div>
            <div style={{ flex: 1 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <div style={{ fontFamily: SANS, fontWeight: 700, fontSize: 18, textTransform: 'lowercase' }}>{e.role}</div>
                <div style={{ fontFamily: MONO, fontSize: 12, opacity: 0.5 }}>{e.time}</div>
              </div>
              <div style={{ fontFamily: MONO, fontSize: 12, opacity: 0.55, marginBottom: 8 }}>{e.org} / {e.loc}</div>
              {e.bullets.map((b, j) => <div key={j} style={{ fontFamily: SANS, fontSize: 14, lineHeight: 1.5, opacity: 0.85 }}>— {b}</div>)}
            </div>
          </div>
        ))}
      </div>
      <div style={{ display: 'flex' }}>
        <div style={{ flex: 1, padding: '28px 48px', borderRight: `2px solid ${INK}` }}>
          <Label>skills</Label>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
            {SKILLS.map(s => (
              <div key={s.cat}>
                <div style={{ fontFamily: MONO, fontSize: 11, opacity: 0.5, textTransform: 'uppercase' }}>{s.cat}</div>
                <div style={{ fontFamily: SANS, fontSize: 14 }}>{s.items.join(', ')}</div>
              </div>
            ))}
          </div>
        </div>
        <div style={{ width: 300, padding: '28px 48px' }}>
          <Label>education</Label>
          {EDUCATION.map((ed, i) => (
            <div key={i} style={{ marginBottom: 12 }}>
              <div style={{ fontFamily: SANS, fontWeight: 700, fontSize: 14, textTransform: 'lowercase' }}>{ed.title}</div>
              <div style={{ fontFamily: MONO, fontSize: 11, opacity: 0.55 }}>{ed.org} / {ed.time}</div>
            </div>
          ))}
          <Label>languages</Label>
          <div style={{ fontFamily: SANS, fontSize: 14 }}>{LANGS.join(', ')}</div>
        </div>
      </div>
    </Page>
  )
}

Object.assign(window, { CVA, CVB, CVC })
